function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.book}</svg>`;}
const DEFAULT={version:1,name:'Estudante',completed:[],notes:{},attempts:[],cards:{},essays:{},essayChecks:{},daily:{},sessions:[],exam:null,plan:{hours:2,days:6,start:new Date().toISOString().slice(0,10)},lastLesson:null};
let state;try{state={...structuredClone(DEFAULT),...JSON.parse(localStorage.getItem('rumo-pmsc-v1')||'{}')};}catch{state=structuredClone(DEFAULT);}
let storageOK=true;
function save(){try{localStorage.setItem('rumo-pmsc-v1',JSON.stringify(state));}catch{storageOK=false;toast('Não foi possível salvar. Exporte um backup em Configurações.');}}
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function sub(id){return SUBJECTS.find(s=>s.id===id);}
function lessonId(s,i){return `${s.id}:${i}`;}
const totalLessons=SUBJECTS.reduce((n,s)=>n+s.topics.length,0);
const doneCount=()=>state.completed.length;
const pct=s=>Math.round(s.topics.filter((_,i)=>state.completed.includes(lessonId(s,i))).length/s.topics.length*100);
function heading(title,desc,extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;}
function empty(title,desc){return `<div class="empty">${icon('book')}<h3>${title}</h3><p>${desc}</p></div>`;}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const NAV=[['inicio','grid','Visão geral'],['disciplinas','book','Disciplinas'],['plano','calendar','Plano de estudos'],['questoes','list','Questões'],['simulados','target','Simulados'],['flashcards','layers','Flashcards'],['redacao','pen','Redação'],['desempenho','chart','Meu desempenho'],['anotacoes','notes','Anotações'],['edital','shield','Guia do edital']];
$('#nav').innerHTML=NAV.map(([id,ico,label])=>`<a class="nav-link" href="#${id}" data-nav="${id}">${icon(ico)}<span>${label}</span>${id==='redacao'?'<span class="nav-new">20 PTS</span>':''}</a>`).join('');
let route='inicio';let viewToken=0;
function routeTo(){viewToken++;const [page,...args]=(location.hash.slice(1)||'inicio').split('/');route=page;closeMenu();$$('.nav-link').forEach(a=>{const active=a.dataset.nav===(page==='aula'?'disciplinas':page);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#crumb').textContent=page==='aula'?'Sala de estudo':(NAV.find(n=>n[0]===page)?.[2]||'Foco e preparação');$('#profile-name').textContent=state.name;$('.avatar').textContent=state.name.slice(0,1).toUpperCase();const pages={inicio:renderDashboard,disciplinas:()=>renderSubjects(args[0]),aula:()=>renderLesson(args[0],Number(args[1])),plano:renderPlan,questoes:renderPractice,simulados:renderExam,flashcards:renderFlashcards,redacao:renderEssay,desempenho:renderPerformance,anotacoes:renderNotes,edital:renderGuide,foco:renderFocus};(pages[page]||renderDashboard)();window.scrollTo(0,0);}
window.addEventListener('hashchange',routeTo);
function setMain(html){$('#main').innerHTML=html;}
function completedToday(){return ['lesson','practice','review','essay'].filter(k=>state.daily[localDate()]?.[k]).length;}
function dayTasks(){const offset=Math.floor((new Date(localDate()+'T12:00:00')-new Date(state.plan.start+'T12:00:00'))/86400000);const all=SUBJECTS.flatMap(s=>s.topics.map((t,i)=>({s,i,t})));const undone=all.filter(x=>!state.completed.includes(lessonId(x.s,x.i)));const pool=undone.length?undone:all;const a=pool[Math.max(0,offset)%pool.length];const b=pool[(Math.max(0,offset)+13)%pool.length];return [{id:'lesson',title:a.t[0],subject:a.s,time:'35 min',type:'Teoria',href:`#aula/${a.s.id}/${a.i}`},{id:'practice',title:'Treino de questões comentadas',subject:b.s,time:'25 min',type:'Questões',href:'#questoes'},{id:'review',title:'Revisão ativa com flashcards',subject:sub('constitucional'),time:'15 min',type:'Revisão',href:'#flashcards'},{id:'essay',title:'Construir uma tese e dois argumentos',subject:{short:'Redação',color:'#b49462'},time:'25 min',type:'Prática',href:'#redacao'}];}
function renderDashboard(){const attempts=state.attempts;const rate=attempts.length?Math.round(attempts.filter(a=>a.correct).length/attempts.length*100):0;const totalMins=state.sessions.reduce((n,s)=>n+s.minutes,0);const daysLeft=Math.max(0,Math.ceil((new Date('2026-12-13T00:00:00-03:00')-new Date(localDate()+'T00:00:00-03:00'))/86400000));const tasks=dayTasks();const today=state.daily[localDate()]||{};setMain(`${heading(`Sua próxima conquista começa aqui<span class="brand-dot">.</span>`,'Um pouco de foco, todos os dias. Vamos avançar na sua preparação?',`<div class="date-pill">${icon('calendar')}${new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',timeZone:'America/Sao_Paulo'}).format(new Date())}</div>`)}
<section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span> MISSÃO: SOLDADO PMSC 2026</div><h2>A sua farda começa<br>com a sua <em>constância.</em></h2><p>Todo conteúdo estudado é um passo mais perto do seu objetivo. Sua jornada está organizada. Agora, é com você.</p><a class="btn light" href="${state.lastLesson?'#aula/'+state.lastLesson.replace(':','/'):'#disciplinas'}">${icon('play')} ${state.lastLesson?'Continuar de onde parei':'Começar meus estudos'} ${icon('arrow')}</a></div><div class="hero-badge" aria-hidden="true"><span class="star">✦</span>${icon('shield')}<b>PMSC</b><small>PREPARAÇÃO · 2026</small></div></section>
<div class="stats"><div class="stat"><span class="stat-icon">${icon('book')}</span><div class="stat-label">Conteúdo estudado</div><div class="stat-value">${Math.round(doneCount()/totalLessons*100)}<small>%</small></div><div class="stat-foot">${doneCount()} de ${totalLessons} revisões concluídas</div></div><div class="stat"><span class="stat-icon">${icon('list')}</span><div class="stat-label">Questões resolvidas</div><div class="stat-value">${attempts.length}<small> questões</small></div><div class="stat-foot">Cada questão ensina um pouco mais</div></div><div class="stat"><span class="stat-icon">${icon('target')}</span><div class="stat-label">Taxa de acertos</div><div class="stat-value">${rate}<small>%</small></div><div class="stat-foot">${attempts.length?`<strong>${attempts.filter(a=>a.correct).length} respostas corretas</strong>`:'Seu desempenho começa aqui'}</div></div><div class="stat"><span class="stat-icon">${icon('clock')}</span><div class="stat-label">Tempo de foco</div><div class="stat-value">${Math.floor(totalMins/60)}<small>h ${totalMins%60}min</small></div><div class="stat-foot">Registrado pelo cronômetro de foco</div></div></div>
<div class="dashboard-grid"><div><section class="card"><div class="section-head"><div class="head-with-icon"><span class="section-icon">${icon('calendar')}</span><div><h2>Seu roteiro de hoje</h2><p>Pequenas metas. Grandes resultados.</p></div></div><a class="text-link" href="#plano">Ver meu plano ↗</a></div><div>${tasks.map(t=>`<div class="task ${today[t.id]?'completed':''}"><button class="check ${today[t.id]?'checked':''}" data-task="${t.id}" aria-label="${today[t.id]?'Desmarcar':'Concluir'} ${esc(t.title)}" aria-pressed="${!!today[t.id]}">${today[t.id]?'✓':''}</button><div class="task-body"><a href="${t.href}" class="task-title">${esc(t.title)}</a><div class="task-sub"><span class="subject-dot" style="background:${t.subject.color}"></span>${esc(t.subject.short)}<span>·</span>${t.type}</div></div><div class="task-right"><span class="tag ${t.type==='Revisão'?'review':''}">${t.type}</span>${t.time}</div></div>`).join('')}</div><div class="day-summary"><div><span>Seu progresso de hoje</span><b>${completedToday()} de 4 metas concluídas</b></div><div class="progress-track"><div class="progress-fill" style="width:${completedToday()/4*100}%"></div></div></div></section><section class="card focus-card"><div class="head-with-icon">${icon('bulb')}<div><h3>Um bloco de foco faz a diferença.</h3><p>Silencie as distrações e dedique 25 minutos ao seu objetivo.</p></div></div><a class="btn outline" href="#foco">${icon('clock')} Iniciar foco</a></section></div><div class="dashboard-right"><section class="card countdown-card"><div class="countdown-top">${icon('calendar')} O SEU OBJETIVO TEM DATA</div><div class="countdown-number">${daysLeft}<span>${daysLeft===1?'dia':'dias'}</span></div><h3>para a prova da PMSC</h3><div class="countdown-meta">${icon('calendar')} 13 de dezembro de 2026</div><p>Data preliminar · Anexo I do edital</p></section><section class="card week-card"><div class="section-head"><h2>Sua constância na semana</h2>${icon('chart')}</div><div class="week-bars">${Array.from({length:7},(_,i)=>{const d=new Date(localDate()+'T12:00:00');d.setDate(d.getDate()-6+i);const ds=d.toISOString().slice(0,10);const mins=state.sessions.filter(s=>s.date===ds).reduce((n,s)=>n+s.minutes,0);return `<div class="week-col"><div class="week-bar ${i===6?'today':''}" style="height:${Math.max(4,Math.min(75,mins/Math.max(1,state.plan.hours*60)*75))}px" title="${ds}: ${mins} minutos"></div><span>${['D','S','T','Q','Q','S','S'][d.getDay()]}</span></div>`;}).join('')}</div><div class="week-footer"><span>Tempo registrado hoje</span><b>${state.sessions.filter(s=>s.date===localDate()).reduce((n,s)=>n+s.minutes,0)} min</b></div></section></div></div>
<section class="subjects-section"><div class="section-head"><div><h2>Um edital. Nove disciplinas. Um objetivo.</h2><p>O conteúdo organizado para você seguir em frente.</p></div><a class="text-link" href="#disciplinas">Explorar tudo ↗</a></div><div class="subject-grid">${SUBJECTS.map(subjectCard).join('')}</div></section>`);$$('[data-task]').forEach(b=>b.onclick=()=>{state.daily[localDate()]??={};state.daily[localDate()][b.dataset.task]=!state.daily[localDate()][b.dataset.task];save();renderDashboard();});}
function libraryHTML(id){return LEGAL_LIBRARY.filter(x=>!id||x[0]===id).map(([subject,title,url,scope])=>`<a class="resource-link" href="${url}" target="_blank" rel="noopener"><span><b>${title}</b><small class="muted" style="display:block;margin-top:5px">${scope}</small></span><span style="margin-left:12px">↗</span></a>`).join('');}
function subjectCard(s){return `<a class="subject-card" href="#disciplinas/${s.id}" style="--accent:${s.color}"><div class="subject-card-top"><span class="subject-ico">${icon(s.icon)}</span><span class="weight">${s.count} questões · ${Math.round(s.count/60*100)}%</span></div><h3>${s.name}</h3><p>${s.topics.length} revisões guiadas · ${s.group}</p><div class="subject-meta"><span>${s.topics.filter((_,i)=>state.completed.includes(lessonId(s,i))).length}/${s.topics.length} concluídas</span><span>${pct(s)}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${pct(s)}%"></div></div></a>`;}
function renderSubjects(id){const s=sub(id);if(s){setMain(`<a class="back-link" href="#disciplinas">${icon('back')} Todas as disciplinas</a>${heading(s.name,`${s.group} · ${s.count} questões na prova · ${s.topics.length} revisões guiadas`)}<div class="two-col"><section><div class="lesson-list">${s.topics.map((t,i)=>`<a class="lesson-row" href="#aula/${s.id}/${i}"><span class="check ${state.completed.includes(lessonId(s,i))?'checked':''}">${state.completed.includes(lessonId(s,i))?'✓':''}</span><span class="lesson-index">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(t[0])}</h3><small>Leitura orientada · Revisão ativa · Anotações</small></div><span class="arrow">↗</span></a>`).join('')}</div></section><aside class="stack sticky"><div class="card"><span class="eyebrow muted">SEU PROGRESSO</span><div class="result-score" style="font-size:40px">${pct(s)}<small>%</small></div><div class="progress-track"><div class="progress-fill" style="width:${pct(s)}%"></div></div><p class="small muted" style="margin-top:15px">${s.source}</p><a class="btn outline" href="${s.url}" target="_blank" rel="noopener">${icon('link')} Consultar fonte oficial</a></div><div class="card"><h3>Biblioteca da disciplina</h3><div class="stack">${libraryHTML(s.id)||`<a class="text-link" href="${s.url}" target="_blank" rel="noopener">Consultar referência ↗</a>`}</div></div><div class="notice" style="margin:0">As revisões são sínteses autorais de apoio. Para cobrir integralmente leis e jurisprudência, faça também a leitura dos textos oficiais e do conteúdo programático.</div><button class="btn" id="subject-practice">${icon('list')} Treinar esta disciplina</button></aside></div>`);$('#subject-practice').onclick=()=>{practiceFilter=s.id;location.hash='questoes';};return;}
setMain(`${heading('Seu mapa até a aprovação.','Nove disciplinas, organizadas de acordo com o Anexo II do edital.')}<div class="toolbar"><input class="input" id="subject-search" aria-label="Buscar disciplina ou conteúdo" placeholder="Buscar disciplina, lei ou conteúdo…"><div class="chips">${['Todas','Direito','Legislação','Conhecimentos Comuns'].map((g,i)=>`<button class="chip ${i?'':'active'}" data-group="${g}">${g}</button>`).join('')}</div></div><div id="subjects-results" class="subject-grid"></div><div class="notice info">${totalLessons} revisões guiadas + conteúdo programático integral. A marcação de conclusão é pessoal e não significa domínio integral da disciplina.</div>`);let group='Todas';const filter=()=>{const q=$('#subject-search').value.toLocaleLowerCase('pt-BR');const results=SUBJECTS.filter(s=>(group==='Todas'||s.group===group)&&`${s.name} ${s.source} ${s.topics.map(t=>t[0]).join(' ')}`.toLocaleLowerCase('pt-BR').includes(q));$('#subjects-results').innerHTML=results.length?results.map(subjectCard).join(''):empty('Nenhuma disciplina encontrada','Tente outro termo de busca.');};$('#subject-search').oninput=filter;$$('[data-group]').forEach(b=>b.onclick=()=>{group=b.dataset.group;$$('[data-group]').forEach(c=>c.classList.toggle('active',c===b));filter();});filter();}
function renderLesson(subject,index){const s=sub(subject);const t=s?.topics[index];if(!t){setMain(empty('Revisão não encontrada','Acesse Disciplinas para escolher um conteúdo.'));return;}const id=lessonId(s,index);state.lastLesson=id;save();setMain(`<a class="back-link" href="#disciplinas/${s.id}">${icon('back')} ${s.name}</a>${heading(esc(t[0]),`REVISÃO ${String(index+1).padStart(2,'0')} DE ${s.topics.length} · MATERIAL AUTORAL`)}<div class="two-col"><article class="card lesson-prose"><span class="eyebrow muted">ENTENDA O ESSENCIAL</span><h2>O ponto de partida</h2><p>${esc(t[1])}</p><h2>Como isso aparece na prova</h2><p>${esc(t[2])}</p><h2>Atenção na revisão</h2><p>${esc(t[3])}</p><h2>Estude de forma ativa</h2><ol><li>Feche o material e explique o tema com suas próprias palavras.</li><li>Localize a regra ou conceito na fonte de referência e registre as exceções.</li><li>Elabore um exemplo e um contraexemplo. Qual palavra mudaria a resposta?</li><li>Resolva as questões disponíveis da disciplina e revise os comentários.</li></ol><div class="source-box"><b>Escopo do edital e referência</b><p>${esc(s.source)}</p><a href="${s.url}" target="_blank" rel="noopener">Abrir fonte oficial ↗</a> · <a href="assets/edital-pmsc-2026.pdf#page=29" target="_blank" rel="noopener">Conferir Anexo II ↗</a></div><div class="lesson-tools"><button class="btn" id="mark-done">${icon('check')} ${state.completed.includes(id)?'Revisão concluída — desmarcar':'Marcar revisão como concluída'}</button><button class="btn outline" id="lesson-print">Imprimir revisão</button></div><div class="question-actions">${index>0?`<a class="btn outline" href="#aula/${s.id}/${index-1}">← Anterior</a>`:'<span></span>'}${index<s.topics.length-1?`<a class="btn outline" href="#aula/${s.id}/${index+1}">Próxima revisão →</a>`:`<a class="btn outline" href="#disciplinas/${s.id}">Voltar à disciplina →</a>`}</div></article><aside class="stack sticky"><section class="card"><h2>Seu caderno</h2><p class="small muted">Dúvidas, exceções e o que você quer lembrar.</p><textarea class="notes" id="lesson-notes" placeholder="Escreva com suas palavras…" aria-label="Anotações desta revisão">${esc(state.notes[id]||'')}</textarea><div class="small muted" id="note-save" role="status">Salvo automaticamente neste navegador</div></section><section class="card"><h3>Revisão espaçada</h3><p class="small muted">Sugestão de método: reveja este conteúdo em 1, 7 e 30 dias. Use os flashcards para recuperar a informação sem consultar o material.</p><a class="btn outline" href="#flashcards">${icon('layers')} Ir para flashcards</a></section></aside></div>`);$('#mark-done').onclick=()=>{state.completed=state.completed.includes(id)?state.completed.filter(x=>x!==id):[...state.completed,id];save();renderLesson(subject,index);toast(state.completed.includes(id)?'Mais um passo concluído. Continue assim!':'Revisão desmarcada.');};$('#lesson-notes').oninput=e=>{state.notes[id]=e.target.value;save();$('#note-save').textContent=storageOK?'Anotação salva ✓':'Falha ao salvar — exporte seu backup';};$('#lesson-print').onclick=()=>window.print();}
let practiceFilter='all',practiceMode='all',practiceQueue=[],practiceAt=0,practiceSelected=null,practiceRevealed=false,practiceOrder=[];
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function orderQuestion(q){return shuffle([0,1,2,3,4]);}
function availableQuestions(){const last=new Map;state.attempts.forEach(a=>last.set(a.id,a.correct));return QUESTIONS.filter(q=>(practiceFilter==='all'||q.subject===practiceFilter)&&(practiceMode==='wrong'?last.get(q.id)===false:practiceMode==='unseen'?!last.has(q.id):true));}
function startPractice(){practiceQueue=shuffle(availableQuestions());practiceAt=0;practiceSelected=null;practiceRevealed=false;practiceOrder=practiceQueue.length?orderQuestion(practiceQueue[0]):[];renderPracticeQuestion();}
function renderPractice(){setMain(`${heading('Transforme dúvidas em acertos.','Questões autorais, com comentários para aprender em cada tentativa.')}<div class="toolbar"><select id="practice-subject" aria-label="Disciplina"><option value="all">Todas as disciplinas</option>${SUBJECTS.map(s=>`<option value="${s.id}" ${s.id===practiceFilter?'selected':''}>${s.name}</option>`).join('')}</select><div class="chips"><button class="chip ${practiceMode==='all'?'active':''}" data-mode="all">Todas · 60</button><button class="chip ${practiceMode==='wrong'?'active':''}" data-mode="wrong">Caderno de erros</button><button class="chip ${practiceMode==='unseen'?'active':''}" data-mode="unseen">Ainda não resolvidas</button></div><button class="btn outline" id="reshuffle">Embaralhar</button></div><div class="notice">Banco inicial de 60 questões autorais de revisão. Não são questões oficiais da AOCP e não esgotam o conteúdo programático. No caderno de erros, vale sua última resposta a cada questão.</div><div id="practice-area"></div>`);$('#practice-subject').onchange=e=>{practiceFilter=e.target.value;startPractice();};$$('[data-mode]').forEach(b=>b.onclick=()=>{practiceMode=b.dataset.mode;$$('[data-mode]').forEach(c=>c.classList.toggle('active',c===b));startPractice();});$('#reshuffle').onclick=startPractice;startPractice();}
function renderPracticeQuestion(){const host=$('#practice-area');if(!host)return;if(!practiceQueue.length){host.innerHTML=empty('Nenhuma questão neste filtro','Escolha outra disciplina ou volte ao filtro “Todas”.');return;}if(practiceAt>=practiceQueue.length){host.innerHTML=`<div class="card center" style="text-align:center"><h2>Bloco de treino concluído!</h2><p class="muted">Você percorreu ${practiceQueue.length} questões. Volte aos comentários e revise os pontos que ainda geram dúvida.</p><button class="btn" id="restart-practice">Treinar novamente</button> <a href="#desempenho" class="btn outline">Ver desempenho</a></div>`;$('#restart-practice').onclick=startPractice;return;}const q=practiceQueue[practiceAt],s=sub(q.subject);host.innerHTML=`<section class="card q-card"><div class="q-meta"><span class="tag">${s.short}</span><span>Questão ${practiceAt+1} de ${practiceQueue.length}</span><span>· Autoral</span></div><h2 class="question-prompt">${esc(q.prompt)}</h2><div>${practiceOrder.map((oi,i)=>`<button class="option ${practiceSelected===oi?'selected':''} ${practiceRevealed?(oi===0?'correct':oi===practiceSelected?'incorrect':''):''}" data-option="${oi}" ${practiceRevealed?'disabled':''}><span class="letter">${'ABCDE'[i]}</span><span>${esc(q.options[oi])}</span>${practiceRevealed&&oi===0?'<span style="margin-left:auto">✓</span>':''}</button>`).join('')}</div>${practiceRevealed?`<div class="explanation ${practiceSelected!==0?'wrong':''}" role="status"><strong>${practiceSelected===0?'Você acertou. Bom trabalho!':'Vamos entender este ponto.'}</strong>${esc(q.explanation)}</div>`:''}<div class="question-actions"><button class="btn outline" id="skip-question">Pular questão</button>${practiceRevealed?'<button class="btn" id="next-question">Próxima questão →</button>':`<button class="btn" id="confirm-answer" ${practiceSelected===null?'disabled':''}>Confirmar resposta</button>`}</div></section>`;$$('[data-option]',host).forEach(b=>b.onclick=()=>{practiceSelected=Number(b.dataset.option);renderPracticeQuestion();});$('#skip-question').onclick=nextPractice;if(practiceRevealed)$('#next-question').onclick=nextPractice;else $('#confirm-answer').onclick=()=>{if(practiceSelected===null)return;state.attempts.push({id:q.id,subject:q.subject,correct:practiceSelected===0,selected:practiceSelected,date:localDate(),time:Date.now(),mode:'practice'});save();practiceRevealed=true;renderPracticeQuestion();};}
function nextPractice(){practiceAt++;practiceSelected=null;practiceRevealed=false;practiceOrder=practiceQueue[practiceAt]?orderQuestion(practiceQueue[practiceAt]):[];renderPracticeQuestion();}
function renderExam(){const e=state.exam;if(e&&!e.finished){renderActiveExam();return;}if(e?.finished){renderExamResult();return;}setMain(`${heading('Treine para o dia da sua conquista.','Um simulado com a distribuição e o tempo previstos no edital.')}<div class="two-col"><section class="card"><span class="eyebrow muted">SIMULADO COMPLETO · PMSC 2026</span><h2 style="margin-top:14px;font-size:25px">Um ensaio para a sua melhor versão.</h2><p class="muted">60 questões objetivas, cinco alternativas e uma resposta correta. O cronômetro de 5 horas contempla também o tempo de redação e de preenchimento da folha na prova real.</p><div class="rules-grid"><div class="rule"><strong>60</strong><span>questões · 1 ponto cada</span></div><div class="rule"><strong>5h</strong><span>tempo total de prova</span></div><div class="rule"><strong>30/60</strong><span>mínimo, sem zerar áreas</span></div></div><div class="notice">Este simulado usa o mesmo banco de 60 questões autorais da área de treino. Repeti-lo não oferece questões inéditas. A redação é praticada separadamente na oficina.</div><button class="btn" id="start-exam">${icon('play')} Iniciar simulado completo</button></section><section class="card"><h2>Distribuição da prova</h2><div class="table-scroll"><table><thead><tr><th>Disciplina</th><th>Questões</th></tr></thead><tbody>${SUBJECTS.map(s=>`<tr><td>${s.short}</td><td>${s.count}</td></tr>`).join('')}</tbody></table></div></section></div>`);$('#start-exam').onclick=()=>{const qs=shuffle(QUESTIONS);state.exam={started:Date.now(),deadline:Date.now()+5*3600000,ids:qs.map(q=>q.id),orders:Object.fromEntries(qs.map(q=>[q.id,orderQuestion(q)])),answers:{},index:0,finished:false};save();renderActiveExam();};}
function renderActiveExam(){const e=state.exam;if(Date.now()>=e.deadline){finishExam();return;}const q=QUESTIONS.find(q=>q.id===e.ids[e.index]);setMain(`${heading('Simulado em andamento.','Responda no seu ritmo. As respostas são salvas a cada seleção.')}<div class="exam-layout"><div class="card q-card"><div class="q-meta"><span class="tag">${sub(q.subject).short}</span><span>Questão ${e.index+1} de 60</span></div><h2 class="question-prompt">${esc(q.prompt)}</h2>${e.orders[q.id].map((oi,i)=>`<button class="option ${e.answers[q.id]===oi?'selected':''}" data-exam-answer="${oi}" aria-pressed="${e.answers[q.id]===oi}"><span class="letter">${'ABCDE'[i]}</span>${esc(q.options[oi])}</button>`).join('')}<div class="question-actions"><button class="btn outline" id="exam-prev" ${e.index===0?'disabled':''}>← Anterior</button><button class="btn outline" id="clear-exam-answer">Limpar resposta</button><button class="btn" id="exam-next">${e.index===59?'Revisar respostas':'Próxima →'}</button></div></div><aside class="card sticky exam-sidebar"><span class="eyebrow muted">TEMPO RESTANTE</span><div class="exam-clock" id="exam-clock" aria-live="off"></div><p class="small muted">${Object.keys(e.answers).length}/60 respostas marcadas</p><div class="exam-map">${e.ids.map((id,i)=>`<button data-exam-goto="${i}" class="${id in e.answers?'answered':''} ${e.index===i?'current':''}" aria-label="Questão ${i+1}${id in e.answers?', respondida':''}">${i+1}</button>`).join('')}</div><p class="small muted">Verde: respondida · Contorno: atual</p><button class="btn" style="width:100%" id="finish-exam">Finalizar simulado</button><p class="small muted" style="margin-top:10px">O tempo continua correndo ao sair desta página.</p></aside></div>`);$$('[data-exam-answer]').forEach(b=>b.onclick=()=>{e.answers[q.id]=Number(b.dataset.examAnswer);save();renderActiveExam();});$$('[data-exam-goto]').forEach(b=>b.onclick=()=>{e.index=Number(b.dataset.examGoto);save();renderActiveExam();});$('#exam-prev').onclick=()=>{if(e.index>0)e.index--;save();renderActiveExam();};$('#exam-next').onclick=()=>{if(e.index<59){e.index++;save();renderActiveExam();}else $('#finish-exam').focus();};$('#clear-exam-answer').onclick=()=>{delete e.answers[q.id];save();renderActiveExam();};$('#finish-exam').onclick=()=>{showModal('Finalizar o simulado?',`<p>Você marcou ${Object.keys(e.answers).length} de 60 respostas. Questões sem resposta valem zero. Ao finalizar, você verá os comentários e o resultado por disciplina.</p><div class="setting-actions"><button class="btn" id="confirm-finish">Finalizar e ver resultado</button><button class="btn outline" id="keep-exam">Continuar respondendo</button></div>`);$('#confirm-finish').onclick=()=>{$('#modal').close();finishExam();};$('#keep-exam').onclick=()=>$('#modal').close();};updateExamClock();}
function updateExamClock(){if(!state.exam||state.exam.finished)return;if(Date.now()>=state.exam.deadline){finishExam();return;}const el=$('#exam-clock');if(el){const secs=Math.max(0,Math.ceil((state.exam.deadline-Date.now())/1000));el.textContent=[Math.floor(secs/3600),Math.floor(secs%3600/60),secs%60].map(n=>String(n).padStart(2,'0')).join(':');}}
function finishExam(){const e=state.exam;if(!e||e.finished)return;e.finished=true;e.finishedAt=Date.now();e.score=e.ids.filter(id=>e.answers[id]===0).length;for(const id of e.ids){const q=QUESTIONS.find(q=>q.id===id);state.attempts.push({id,subject:q.subject,correct:e.answers[id]===0,selected:e.answers[id]??null,date:localDate(),time:Date.now(),mode:'exam'});}save();if(route==='simulados')renderExamResult();else toast('O tempo do simulado terminou. Confira seu resultado em Simulados.');}
function renderExamResult(){const e=state.exam;const zero=SUBJECTS.filter(s=>!e.ids.some(id=>QUESTIONS.find(q=>q.id===id).subject===s.id&&e.answers[id]===0));const met=e.score>=30&&zero.length===0;setMain(`${heading('Cada resultado é um novo ponto de partida.','Confira sua pontuação e transforme os erros no próximo plano de revisão.')}<div class="two-col"><section class="card"><span class="eyebrow muted">RESULTADO DO SIMULADO AUTORAL</span><div class="result-score">${e.score}<small>/60 pontos</small></div><h2>${met?'Critério mínimo objetivo atingido neste treino':'Ainda há pontos para fortalecer'}</h2><p class="muted small">${met?'Pelo menos 30 pontos, sem zerar disciplina. Isso não garante classificação no concurso.':`O critério é 30 pontos e nenhuma área zerada.${zero.length?' Áreas zeradas: '+zero.map(s=>s.short).join(', ')+'.':''}`}</p><div class="notice">O edital usa o termo “áreas de conhecimento” no item 8.4. Para um treino conservador, este site verifica também se houve zero em qualquer uma das nove disciplinas. Confirme a aplicação oficial com a banca. Redação e demais critérios não estão avaliados aqui.</div><div class="setting-actions"><button class="btn" id="new-exam">Fazer novo simulado</button><a class="btn outline" href="#redacao">Praticar redação</a><button class="btn outline" id="export-result">Exportar resultado</button></div><div class="table-scroll"><table><thead><tr><th>Disciplina</th><th>Acertos</th><th>Aproveitamento</th></tr></thead><tbody>${SUBJECTS.map(s=>{const hits=e.ids.filter(id=>id.startsWith(s.id+'-')&&e.answers[id]===0).length;return `<tr><td>${s.short}</td><td>${hits}/${s.count}</td><td>${Math.round(hits/s.count*100)}%</td></tr>`;}).join('')}</tbody></table></div></section><aside class="card"><h2>Como usar este resultado</h2><p class="small muted">1. Leia o comentário de cada erro.<br>2. Retome a fonte oficial.<br>3. Anote a regra que faltou.<br>4. Teste sua lembrança sem consultar o material.</p><p class="small muted">O banco é pequeno e autoral. Acerte pelo raciocínio, evitando memorizar a posição das alternativas.</p></aside></div><section style="margin-top:25px"><h2>Correção comentada</h2>${e.ids.map((id,i)=>{const q=QUESTIONS.find(q=>q.id===id),a=e.answers[id];return `<details class="card" style="margin:10px 0;padding:17px"><summary>${i+1}. ${a===0?'✓':'○'} ${esc(q.prompt)}</summary><div class="small" style="margin-top:15px"><p>Sua resposta: ${a===undefined?'Em branco':esc(q.options[a])}</p><p><b>Correta:</b> ${esc(q.options[0])}</p><p>${esc(q.explanation)}</p></div></details>`;}).join('')}</section>`);$('#new-exam').onclick=()=>{showModal('Começar um novo simulado?',`<p>O resultado atual será substituído, mas suas tentativas continuarão no desempenho. Você pode exportar o resultado antes de continuar.</p><button class="btn" id="confirm-new-exam">Começar outro simulado</button>`);$('#confirm-new-exam').onclick=()=>{state.exam=null;save();$('#modal').close();renderExam();};};$('#export-result').onclick=()=>download('resultado-pmsc.json',JSON.stringify(e,null,2));}
let flashSubject='all',flashDueOnly=false,flashQueue=[],flashAt=0,flashFlipped=false;
function renderFlashcards(){setMain(`${heading('Lembrar é uma habilidade. Treine.','Recupere a informação antes de virar o cartão. Depois, escolha quando revisar.')}<div class="toolbar"><select id="flash-subject" aria-label="Disciplina dos flashcards"><option value="all">Todas as disciplinas</option>${SUBJECTS.map(s=>`<option value="${s.id}" ${flashSubject===s.id?'selected':''}>${s.name}</option>`).join('')}</select><button class="chip ${flashDueOnly?'active':''}" id="due-only">Somente revisões de hoje</button><span class="small muted">60 cartões de revisão · derivados do banco autoral</span></div><div class="center" id="flash-area"></div>`);$('#flash-subject').onchange=e=>{flashSubject=e.target.value;startFlash();};$('#due-only').onclick=()=>{flashDueOnly=!flashDueOnly;renderFlashcards();};startFlash();}
function startFlash(){flashQueue=shuffle(QUESTIONS.filter(q=>(flashSubject==='all'||q.subject===flashSubject)&&(!flashDueOnly||!state.cards[q.id]||state.cards[q.id].due<=Date.now())));flashAt=0;flashFlipped=false;renderFlash();}
function renderFlash(){const host=$('#flash-area');if(!host)return;if(!flashQueue.length){host.innerHTML=empty('Revisões em dia!','Nenhum cartão pendente neste filtro. Volte mais tarde ou veja todos os cartões.');return;}if(flashAt>=flashQueue.length){host.innerHTML=`<div class="card" style="text-align:center"><h2>Boa sessão de revisão!</h2><p class="muted">Seus próximos intervalos foram salvos. Continue estudando as fontes e pratique os conceitos em novos exemplos.</p><button class="btn" id="flash-restart">Revisar novamente</button></div>`;$('#flash-restart').onclick=startFlash;return;}const q=flashQueue[flashAt];host.innerHTML=`<div class="section-head"><span class="small muted">${sub(q.subject).name}</span><span class="small muted">Cartão ${flashAt+1} de ${flashQueue.length}</span></div><button class="flashcard" id="flip-card" aria-label="${flashFlipped?'Mostrar pergunta':'Revelar resposta'}"><span class="eyebrow">${flashFlipped?'A RESPOSTA':'RESGATE NA MEMÓRIA'}</span><h2>${esc(flashFlipped?q.options[0]:q.prompt)}</h2>${flashFlipped?`<p class="muted">${esc(q.explanation)}</p>`:''}<span class="small muted">${flashFlipped?'Clique para voltar à pergunta':'Pense na resposta. Clique para revelar.'}</span></button>${flashFlipped?`<div class="flash-actions"><button class="btn outline" data-flash-rate="0">Rever agora</button><button class="btn outline" data-flash-rate="1">Difícil · 1 dia</button><button class="btn" data-flash-rate="7">Lembrei · 7 dias</button></div>`:'<div class="flash-actions"><button class="btn" id="reveal-card">Revelar resposta</button><button class="btn outline" id="skip-card">Pular</button></div>'}<p class="small muted" style="text-align:center">O agendamento usa os intervalos escolhidos por você. Cartões adiados saem do filtro de revisões pendentes.</p>`;$('#flip-card').onclick=()=>{flashFlipped=!flashFlipped;renderFlash();};if(!flashFlipped){$('#reveal-card').onclick=()=>{flashFlipped=true;renderFlash();};$('#skip-card').onclick=()=>{flashAt++;renderFlash();};}$$('[data-flash-rate]').forEach(b=>b.onclick=()=>{const days=Number(b.dataset.flashRate);state.cards[q.id]={due:Date.now()+days*86400000,reviews:(state.cards[q.id]?.reviews||0)+1,last:Date.now()};save();if(days===0)flashQueue.push(q);flashAt++;flashFlipped=false;renderFlash();});}
function renderPlan(){const p=state.plan;setMain(`${heading('Organize a semana. Proteja o seu objetivo.','Um ciclo equilibrado, com prioridade proporcional ao número de questões.')}<div class="two-col"><section><div class="notice info" style="margin-top:0">O plano reserva 10% do tempo semanal para redação e distribui o restante pelas nove disciplinas, na proporção das questões. Em cada bloco, use metade do tempo para teoria, um quarto para questões e um quarto para revisão. É uma sugestão de método, não uma exigência do edital.</div><div id="plan-days"></div></section><aside class="stack sticky"><form class="card plan-form" id="plan-form"><h2>Seu ritmo de estudo</h2><div><label class="form-label" for="plan-hours">Horas por dia</label><input type="number" min="0.5" max="12" step="0.5" id="plan-hours" class="input" value="${p.hours}" required></div><div><label class="form-label" for="plan-days-input">Dias de estudo por semana</label><select id="plan-days-input">${[3,4,5,6,7].map(n=>`<option ${n===p.days?'selected':''}>${n}</option>`).join('')}</select></div><div><label class="form-label" for="plan-start">Início da semana</label><input id="plan-start" class="input" type="date" value="${p.start}" required></div><button class="btn" type="submit">Atualizar meu plano</button><button class="btn outline" type="button" id="export-plan">${icon('download')} Exportar agenda (.ics)</button></form><section class="card"><h3>Priorize sem abandonar matérias</h3><p class="small muted">Institucional representa 10/60 questões; Constitucional e Português, 8/60 cada. A pontuação mínima não basta se houver zero na área exigida. Reserve espaço para todas.</p><a class="text-link" href="#edital">Conferir distribuição e critérios ↗</a></section></aside></div>`);$('#plan-form').onsubmit=e=>{e.preventDefault();const hours=Number($('#plan-hours').value),days=Number($('#plan-days-input').value),start=$('#plan-start').value;if(hours<.5||hours>12||!start)return;state.plan={hours,days,start};save();renderPlan();toast('Plano atualizado para o seu ritmo.');};$('#export-plan').onclick=exportCalendar;renderPlanDays();}
function getPlan(){
 const {hours,days,start}=state.plan, perDay=Math.round(hours*60),weekly=perDay*days;
 const essayMinutes=Math.max(5,Math.round(weekly*.1)),objectiveMinutes=weekly-essayMinutes;
 const ranked=[...SUBJECTS].sort((a,b)=>b.count-a.count);
 const allocations=ranked.map(s=>({s,minutes:Math.floor(objectiveMinutes*s.count/60),fraction:objectiveMinutes*s.count/60%1}));
 let remainder=objectiveMinutes-allocations.reduce((n,x)=>n+x.minutes,0);
 [...allocations].sort((a,b)=>b.fraction-a.fraction).forEach(x=>{if(remainder>0){x.minutes++;remainder--;}});
 const queue=allocations.map(x=>({title:`Estudo ativo · ${x.s.short}`,subject:x.s.id,minutes:x.minutes}));
 queue.push({title:'Oficina de redação',subject:'redacao',minutes:essayMinutes});
 let at=0;
 return Array.from({length:days},(_,i)=>{
  const d=new Date(start+'T12:00:00');d.setDate(d.getDate()+i);let available=perDay;const sessions=[];
  while(available>0&&at<queue.length){const block=queue[at],take=Math.min(available,block.minutes);if(take>0)sessions.push({...block,minutes:take});block.minutes-=take;available-=take;if(!block.minutes)at++;}
  return {date:d.toISOString().slice(0,10),label:new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit'}).format(d),sessions};
 });
}
function renderPlanDays(){$('#plan-days').innerHTML=getPlan().map(d=>`<section class="plan-day"><div class="plan-day-header"><h3>${d.label[0].toUpperCase()+d.label.slice(1)}</h3><span class="small muted">${Math.round(state.plan.hours*60)} minutos</span></div>${d.sessions.map((s,i)=>{const key=`plan-${d.date}-${i}`;return `<div class="task"><button class="check ${state.daily[d.date]?.[key]?'checked':''}" data-plan-key="${key}" data-plan-date="${d.date}" aria-label="Concluir ${s.title}" aria-pressed="${!!state.daily[d.date]?.[key]}">${state.daily[d.date]?.[key]?'✓':''}</button><a class="task-body" href="${s.title.startsWith('Revisão')?'#flashcards':s.title.startsWith('Questões')?'#questoes':s.subject==='redacao'?'#redacao':'#disciplinas/'+s.subject}"><span class="task-title">${s.title}</span><span class="task-sub">${s.subject==='redacao'?'Planejamento, escrita e revisão':'Teoria 50% · Questões 25% · Revisão 25%'}</span></a><span class="small muted">${s.minutes} min</span></div>`;}).join('')}</section>`).join('');$$('[data-plan-key]').forEach(b=>b.onclick=()=>{const date=b.dataset.planDate,key=b.dataset.planKey;state.daily[date]??={};state.daily[date][key]=!state.daily[date][key];save();renderPlanDays();});}
function exportCalendar(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Rumo a Farda//Plano PMSC//PT-BR','CALSCALE:GREGORIAN'];getPlan().forEach((d,i)=>{const stamp=d.date.replaceAll('-','');const next=new Date(d.date+'T12:00:00');next.setDate(next.getDate()+1);lines.push('BEGIN:VEVENT',`UID:pmsc-${stamp}-${i}@rumoafarda.local`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${stamp}`,`DTEND;VALUE=DATE:${next.toISOString().slice(0,10).replaceAll('-','')}`,`SUMMARY:Estudo PMSC - ${state.plan.hours}h`,`DESCRIPTION:${d.sessions.map(s=>s.title+' ('+s.minutes+' min)').join(' / ')}`,'END:VEVENT');});lines.push('END:VCALENDAR');download('meu-plano-pmsc.ics',lines.join('\r\n'),'text/calendar;charset=utf-8');}
let essayTheme=0;
const RUBRIC=['Meu texto responde ao tema e delimita uma tese.','Cada desenvolvimento apresenta argumento e explicação.','Usei repertório pertinente sem inventar dados ou citações.','Conectei os parágrafos com progressão lógica.','Minha conclusão retoma a tese de forma coerente.','Revisei ortografia, regência, concordância e pontuação.','Treinei a versão manuscrita entre 20 e 30 linhas.','Evitei assinatura ou marca de identificação no texto.'];
function renderEssay(){const theme=ESSAY_THEMES[essayTheme];setMain(`${heading('Sua ideia, com clareza e argumento.','Uma oficina de redação dissertativa voltada aos temas de Ordem Pública.')}<div class="notice" style="margin-top:0">O edital exige 20 a 30 linhas manuscritas, até 20 pontos e nota mínima 10. A correção está limitada à classificação indicada no item 11.1 (até a 2.000ª posição, com empates). Este espaço não faz correção automática nem estima sua nota.</div><div class="toolbar"><select id="essay-theme" aria-label="Tema de redação">${ESSAY_THEMES.map((t,i)=>`<option value="${i}" ${i===essayTheme?'selected':''}>${i+1}. ${t[0]}</option>`).join('')}</select><button class="btn outline" id="export-essay">${icon('download')} Exportar texto</button></div><div class="two-col"><section><article class="card"><span class="eyebrow muted">PROPOSTA AUTORAL DE TREINO</span><h2 style="margin-top:12px">${theme[0]}</h2><p>${theme[1]}</p><div class="source-box" style="margin-top:0"><b>Pistas de repertório</b><p style="margin:6px 0 0">${theme[2]}</p></div><label class="form-label" for="essay-text" style="margin-top:20px">Seu rascunho</label><textarea id="essay-text" class="essay-text" placeholder="Antes de escrever, defina sua tese e dois argumentos…">${esc(state.essays[essayTheme]||'')}</textarea><div class="essay-meta"><span id="essay-words"></span><span id="essay-chars"></span><span id="essay-save" role="status">Salvo neste navegador</span></div><p class="small muted">Linhas na tela não equivalem às linhas da folha oficial. Faça também o treino manuscrito com tempo cronometrado.</p></article><details class="card" style="margin-top:18px"><summary><b>Roteiro de construção: do planejamento à revisão</b></summary><div class="lesson-prose" style="font-size:12px;margin-top:20px"><h3>1. Planeje em cinco minutos</h3><p>Identifique o recorte temático. Escreva sua posição em uma frase e escolha dois argumentos diferentes que a sustentem. Evite fugir para temas apenas próximos.</p><h3>2. Apresente tese e percurso</h3><p>Na introdução, contextualize sem generalizações vazias e indique a tese. Um parágrafo não precisa anunciar todos os detalhes, mas deve orientar o leitor.</p><h3>3. Desenvolva com evidências</h3><p>Comece pelo argumento, explique a relação causal ou a consequência e use exemplo ou referência verificável. Não invente estatísticas nem atribua frases a autores sem segurança.</p><h3>4. Conclua e revise</h3><p>Retome o raciocínio sem acrescentar argumento central novo. O edital pede dissertação: não imponha automaticamente o modelo de intervenção do ENEM. Revise coesão, clareza e norma-padrão.</p></div></details></section><aside class="stack sticky"><section class="card"><h2>Checklist de revisão</h2><p class="small muted">Marque depois de reler seu texto.</p><div class="rubric">${RUBRIC.map((r,i)=>`<label><input type="checkbox" data-rubric="${i}" ${state.essayChecks[essayTheme]?.includes(i)?'checked':''}>${r}</label>`).join('')}</div></section><section class="card"><h3>Entenda a fórmula do edital</h3><div class="formula">NPR = NC − NE ÷ TL</div><p class="small muted">Calculadora manual, para valores avaliados por um corretor. NC: conteúdo (0–20); NE: erros; TL: linhas efetivamente escritas.</p><div class="formula-inputs"><div><label class="form-label" for="nc">NC</label><input class="input" id="nc" type="number" min="0" max="20" step="0.1" placeholder="0–20"></div><div><label class="form-label" for="ne">NE</label><input class="input" id="ne" type="number" min="0" step="1" placeholder="Erros"></div><div><label class="form-label" for="tl">TL</label><input class="input" id="tl" type="number" min="1" max="30" step="1" placeholder="Linhas"></div></div><div id="formula-result" class="formula-result" role="status">—</div><p class="small muted">Abaixo de 20 linhas: dedução de 0,20 por linha faltante. Acima de 30: trechos excedentes desconsiderados. Resultado negativo é limitado a zero conforme o edital.</p></section><a class="btn outline" href="#foco">${icon('clock')} Cronometrar a escrita</a></aside></div>`);$('#essay-theme').onchange=e=>{essayTheme=Number(e.target.value);renderEssay();};const update=()=>{const text=$('#essay-text').value;$('#essay-words').textContent=`${text.trim()?text.trim().split(/\s+/).length:0} palavras`;$('#essay-chars').textContent=`${text.length} caracteres`;};$('#essay-text').oninput=e=>{state.essays[essayTheme]=e.target.value;save();$('#essay-save').textContent=storageOK?'Rascunho salvo ✓':'Falha ao salvar — exporte o texto';update();};update();$('#export-essay').onclick=()=>download(`redacao-pmsc-${essayTheme+1}.txt`,`${theme[0]}\n\n${state.essays[essayTheme]||''}`,'text/plain;charset=utf-8');$$('[data-rubric]').forEach(b=>b.onchange=()=>{const checks=new Set(state.essayChecks[essayTheme]||[]);b.checked?checks.add(Number(b.dataset.rubric)):checks.delete(Number(b.dataset.rubric));state.essayChecks[essayTheme]=[...checks];save();});['nc','ne','tl'].forEach(id=>$('#'+id).oninput=()=>{const vals=['nc','ne','tl'].map(k=>$('#'+k).value);if(vals.some(v=>v==='')){$('#formula-result').textContent='—';return;}const[nc,ne,tl]=vals.map(Number);if(nc<0||nc>20||ne<0||!Number.isInteger(ne)||tl<1||tl>30||!Number.isInteger(tl)){$('#formula-result').textContent='Confira os valores.';return;}const value=Math.max(0,nc-ne/tl-Math.max(0,20-tl)*.2);$('#formula-result').textContent=value.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+' pontos';});}
function renderPerformance(){const a=state.attempts;const correct=a.filter(x=>x.correct).length;const allMins=state.sessions.reduce((n,s)=>n+s.minutes,0);const studiedDays=new Set(state.sessions.map(s=>s.date));let streak=0;const d=new Date(localDate()+'T12:00:00');if(!studiedDays.has(localDate()))d.setDate(d.getDate()-1);for(let i=0;i<400;i++){if(!studiedDays.has(d.toISOString().slice(0,10)))break;streak++;d.setDate(d.getDate()-1);}setMain(`${heading('Veja o caminho que você já percorreu.','Dados reais das suas atividades neste navegador. Cada passo conta.')}<div class="stats"><div class="stat"><div class="stat-label">Questões respondidas</div><div class="stat-value">${a.length}</div><div class="stat-foot">Inclui repetições e simulados</div></div><div class="stat"><div class="stat-label">Aproveitamento geral</div><div class="stat-value">${a.length?Math.round(correct/a.length*100):0}<small>%</small></div><div class="stat-foot">${correct} acertos · ${a.length-correct} erros/em branco</div></div><div class="stat"><div class="stat-label">Tempo de foco</div><div class="stat-value">${Math.floor(allMins/60)}<small>h ${allMins%60}min</small></div><div class="stat-foot">${state.sessions.length} sessões registradas</div></div><div class="stat"><div class="stat-label">Constância atual</div><div class="stat-value">${streak}<small> dias</small></div><div class="stat-foot">Dias consecutivos com sessão de foco</div></div></div><div class="two-col"><section class="card"><h2>Acertos por disciplina</h2><p class="small muted">Todas as tentativas registradas, incluindo repetições.</p>${SUBJECTS.map(s=>{const sa=a.filter(x=>x.subject===s.id),hits=sa.filter(x=>x.correct).length;return `<div class="bar-row"><div class="bar-label"><span>${s.name}</span><span class="muted">${hits}/${sa.length} · ${sa.length?Math.round(hits/sa.length*100):0}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${sa.length?hits/sa.length*100:0}%;background:${s.color}"></div></div></div>`;}).join('')}</section><section class="card"><h2>Sua próxima prioridade</h2>${a.length?(()=>{const ranked=SUBJECTS.map(s=>{const sa=a.filter(x=>x.subject===s.id);return{s,rate:sa.length?sa.filter(x=>x.correct).length/sa.length:0,n:sa.length};}).sort((a,b)=>a.rate-b.rate||b.s.count-a.s.count);return ranked.slice(0,3).map(({s,n})=>`<a class="lesson-row" href="#disciplinas/${s.id}" style="margin-top:13px"><span class="subject-ico" style="--accent:${s.color}">${icon(s.icon)}</span><div><h3>${s.short}</h3><small>${n?'Reforce os pontos de dúvida':'Ainda sem respostas registradas'}</small></div><span class="arrow">↗</span></a>`).join('');})():empty('Sua jornada começa agora','Resolva as primeiras questões para identificar seus pontos de revisão.')}<a class="btn outline" href="#questoes" style="margin-top:20px">Praticar questões</a></section></div><section class="card" style="margin-top:20px"><div class="section-head"><h2>Últimas atividades</h2><button class="btn outline" id="export-progress">${icon('download')} Exportar backup completo</button></div>${a.length?`<div class="table-scroll"><table><thead><tr><th>Data</th><th>Disciplina</th><th>Questão</th><th>Resultado</th></tr></thead><tbody>${a.slice(-15).reverse().map(x=>`<tr><td>${x.date.split('-').reverse().join('/')}</td><td>${sub(x.subject)?.short||''}</td><td>${esc(QUESTIONS.find(q=>q.id===x.id)?.prompt||'')}</td><td>${x.correct?'✓ Acerto':'○ Revisar'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">Suas atividades aparecerão aqui quando você começar a praticar.</p>'}</section>`);$('#export-progress').onclick=exportBackup;}
function renderNotes(){const entries=Object.entries(state.notes).filter(([,v])=>v.trim());setMain(`${heading('O seu conhecimento, nas suas palavras.','Suas anotações das revisões, reunidas em um só lugar.')}<div class="toolbar"><input class="input" id="notes-search" placeholder="Buscar nas anotações…" aria-label="Buscar nas anotações"><button class="btn outline" id="export-notes">${icon('download')} Exportar caderno</button></div><div class="note-list" id="notes-results"></div>`);const filter=()=>{const q=$('#notes-search').value.toLowerCase();const filtered=entries.filter(([id,text])=>{const [s,i]=id.split(':');return (text+' '+(sub(s)?.topics[+i]?.[0]||'')).toLowerCase().includes(q);});$('#notes-results').innerHTML=filtered.length?filtered.map(([id,text])=>{const[s,i]=id.split(':');return `<a class="note-preview" href="#aula/${s}/${i}"><span class="eyebrow muted">${sub(s)?.short||'Revisão'}</span><h3 style="margin-top:9px">${esc(sub(s)?.topics[+i]?.[0]||'Anotação')}</h3><p>${esc(text)}</p></a>`;}).join(''):empty('Seu caderno está esperando por você','Abra uma revisão em Disciplinas e registre suas próprias explicações.');};$('#notes-search').oninput=filter;$('#export-notes').onclick=()=>download('caderno-pmsc.txt',entries.map(([id,text])=>{const[s,i]=id.split(':');return `${sub(s)?.name} — ${sub(s)?.topics[+i]?.[0]}\n${text}`;}).join('\n\n──────────\n\n'),'text/plain;charset=utf-8');filter();}
function renderGuide(){setMain(`${heading('Conheça a missão por inteiro.','Regras e conteúdo extraídos do edital enviado — nº 002/CCP/2026.')}<div class="rules-grid"><div class="rule"><strong>500</strong><span>vagas para Soldado QPPM</span></div><div class="rule"><strong>60 + 20</strong><span>pontos: objetiva + redação</span></div><div class="rule"><strong>13/12/26</strong><span>prova · data preliminar</span></div></div><div class="notice">Referência: PDF enviado nesta conversa. Não há monitoramento automático de retificações. Confira sempre as publicações da PMSC e do Instituto AOCP.</div><div class="two-col"><div class="stack"><section class="card"><div class="section-head"><h2>Estrutura e critérios da prova</h2><a class="btn outline" href="assets/edital-pmsc-2026.pdf" target="_blank" rel="noopener">${icon('download')} Edital completo</a></div><div class="table-scroll"><table><thead><tr><th>Área / disciplina</th><th>Questões</th><th>Pontos</th></tr></thead><tbody>${SUBJECTS.map(s=>`<tr><td>${s.name}</td><td>${s.count}</td><td>${s.count.toFixed(2).replace('.',',')}</td></tr>`).join('')}<tr><td><b>Total objetiva</b></td><td><b>60</b></td><td><b>60,00</b></td></tr><tr><td>Redação</td><td>20 a 30 linhas</td><td>20,00</td></tr></tbody></table></div><p class="small" style="margin-top:18px"><b>Item 8.4:</b> pelo menos 50% dos pontos da objetiva e nenhuma área de conhecimento com nota zero, observados os demais critérios de eliminação.</p><p class="small"><b>Redação:</b> nota mínima 10/20. Correção até a 2.000ª posição na objetiva, com os empates no limite e requisitos do item 11.1.</p><p class="small"><b>Tempo:</b> 5 horas para objetiva e redação, incluindo preenchimento das folhas. Cada questão tem cinco alternativas e somente uma correta.</p></section><section class="card"><h2>Conteúdo programático integral</h2><p class="small muted">Transcrição textual do Anexo II, páginas 29–30 do edital. Consulte o PDF para a formatação original.</p><div id="syllabus" class="syllabus">Carregando conteúdo programático…</div></section><section class="card"><h2>Biblioteca de legislação</h2><p class="small muted">30 referências federais e estaduais para acompanhar a leitura. Para normas estaduais sem endereço direto, o link abre o portal oficial de pesquisa.</p><div class="resource-links">${libraryHTML()}</div></section><section class="card"><h2>Fontes para aprofundar e atualizar</h2><p class="small muted">Leitura integral de legislação e jurisprudência complementa as revisões deste site.</p><div class="resource-links">${[['Planalto · Legislação federal','https://www.planalto.gov.br/ccivil_03/'],['ALESC · Legislação catarinense','https://leis.alesc.sc.gov.br/'],['STF · Jurisprudência','https://portal.stf.jus.br/jurisprudencia/'],['STJ · Jurisprudência','https://scon.stj.jus.br/SCON/'],['Instituto AOCP · Publicações','https://www.institutoaocp.org.br/'],['PMSC · Portal institucional','https://www.pm.sc.gov.br/'],['LibreOffice · Documentação','https://documentation.libreoffice.org/pt-br/portugues/'],['Microsoft · Windows','https://support.microsoft.com/pt-br/windows']].map(([name,url])=>`<a class="resource-link" href="${url}" target="_blank" rel="noopener">${name}<span>↗</span></a>`).join('')}</div></section></div><aside class="stack sticky"><section class="card"><h2>Datas para acompanhar</h2>${[['26/10–16/11','Inscrições, até 16h do último dia'],['Até 16/11','Pagamento da taxa'],['02/12','Edital de data, hora e local'],['07/12','Cartão de informação'],['13/12','Provas objetiva e redação'],['14/12','Gabarito preliminar'],['15–16/12','Recursos ao gabarito']].map(([d,t])=>`<div class="timeline-item"><b>${d}</b><span>${t}</span></div>`).join('')}<p class="small muted" style="margin-top:15px">Datas de 2026, conforme cronograma preliminar do Anexo I. Horários conforme publicações oficiais.</p></section><section class="card"><h2>Além da prova escrita</h2><p class="small muted">O concurso também prevê avaliação de saúde e exame toxicológico, TAF, investigação social, avaliação psicológica, documentos e inclusão/matrícula no CFP.</p><p class="small muted">Para o TAF, consulte integralmente o item 13 e o Anexo V. Este site não prescreve treinamento físico nem substitui os índices e procedimentos oficiais.</p><a class="text-link" href="assets/edital-pmsc-2026.pdf#page=31" target="_blank" rel="noopener">Consultar anexos no PDF ↗</a></section><section class="card"><h3>No dia da prova</h3><p class="small muted">Confira local e horário no cartão. O edital pede antecedência mínima de 45 minutos do fechamento do portão, documento oficial, cartão impresso e caneta transparente azul ou preta. Consulte os itens 9 e 11 para todas as condições.</p></section></aside></div>`);const token=viewToken;fetch('assets/programa.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{if(token===viewToken&&$('#syllabus'))$('#syllabus').textContent=d.text;}).catch(()=>{if(token===viewToken&&$('#syllabus'))$('#syllabus').innerHTML='Não foi possível carregar a transcrição. <a href="assets/edital-pmsc-2026.pdf#page=29">Abra o Anexo II no PDF.</a>';});}
let focus={duration:25*60,remaining:25*60,deadline:null,running:false,mode:'study',sessionSubject:'constitucional'};
function renderFocus(){setMain(`${heading('Agora, só o próximo passo.','Um tempo protegido para aprender, sem pressa e sem distrações.')}<div class="center"><section class="card timer"><div class="chips" style="justify-content:center"><button class="chip ${focus.mode==='study'?'active':''}" data-focus-mode="study">Foco · 25 min</button><button class="chip ${focus.mode==='break'?'active':''}" data-focus-mode="break">Pausa · 5 min</button></div><div class="timer-time" id="focus-time">${formatTime(focus.remaining)}</div><p class="muted small" id="focus-status">${focus.running?'Seu tempo está protegido. Concentre-se no essencial.':'Escolha seu conteúdo e comece uma sessão.'}</p><div class="toolbar" style="justify-content:center"><select id="focus-subject" aria-label="Disciplina da sessão" ${focus.running?'disabled':''}>${[...SUBJECTS,{id:'redacao',name:'Redação'}].map(s=>`<option value="${s.id}" ${focus.sessionSubject===s.id?'selected':''}>${s.name}</option>`).join('')}</select><label class="small muted">Minutos <input class="input" style="width:75px;min-width:0" id="focus-duration" type="number" min="1" max="180" value="${Math.round(focus.duration/60)}" ${focus.running?'disabled':''}></label></div><div class="timer-controls"><button class="btn" id="focus-toggle">${focus.running?'Pausar':'Iniciar foco'}</button><button class="btn outline" id="focus-reset">Reiniciar</button></div><p class="small muted" style="margin:22px 0 0">Ao completar uma sessão de foco, o tempo é registrado no seu desempenho.<br>Pausas não contam como estudo. Ao fechar ou recarregar a página, o cronômetro é reiniciado.</p></section><section class="notice info"><b>Um pequeno ritual:</b> defina uma meta concreta, feche as outras abas e deixe o celular longe. No fim, escreva o que conseguiu lembrar sem consultar.</section></div>`);$$('[data-focus-mode]').forEach(b=>b.onclick=()=>{if(focus.running){toast('Pause a sessão antes de trocar o modo.');return;}focus.mode=b.dataset.focusMode;focus.duration=(focus.mode==='study'?25:5)*60;focus.remaining=focus.duration;focus.deadline=null;renderFocus();});$('#focus-subject').onchange=e=>focus.sessionSubject=e.target.value;$('#focus-duration').onchange=e=>{if(focus.running)return;const n=Number(e.target.value);if(n>=1&&n<=180){focus.duration=n*60;focus.remaining=focus.duration;renderFocus();}};$('#focus-toggle').onclick=()=>{if(focus.running){focus.remaining=Math.max(0,Math.ceil((focus.deadline-Date.now())/1000));focus.running=false;}else{focus.deadline=Date.now()+focus.remaining*1000;focus.running=true;}renderFocus();};$('#focus-reset').onclick=()=>{focus.running=false;focus.remaining=focus.duration;focus.deadline=null;renderFocus();};}
function formatTime(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function tick(){updateExamClock();if(!focus.running)return;focus.remaining=Math.max(0,Math.ceil((focus.deadline-Date.now())/1000));const el=$('#focus-time');if(el)el.textContent=formatTime(focus.remaining);if(focus.remaining===0){focus.running=false;if(focus.mode==='study'){state.sessions.push({date:localDate(),minutes:Math.round(focus.duration/60),subject:focus.sessionSubject,time:Date.now()});save();toast('Sessão concluída! Seu tempo de estudo foi registrado.');}else toast('Pausa concluída. Vamos ao próximo passo?');focus.remaining=focus.duration;if(route==='foco')renderFocus();}}
setInterval(tick,1000);
function showModal(title,body){$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" id="close-modal" aria-label="Fechar janela">×</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal();$('#close-modal').onclick=()=>$('#modal').close();}
function showSearch(){showModal('O que vamos estudar?',`<input class="input" style="width:100%" id="search-input" placeholder="Busque por tema, disciplina ou lei…" aria-label="Busca geral"><div class="modal-results" id="search-results"></div>`);const input=$('#search-input');input.oninput=()=>{const q=input.value.trim().toLocaleLowerCase('pt-BR');const results=q?SUBJECTS.flatMap(s=>s.topics.map((t,i)=>({s,t,i}))).filter(x=>(x.s.name+' '+x.t.join(' ')).toLocaleLowerCase('pt-BR').includes(q)).slice(0,25):[];$('#search-results').innerHTML=q?(results.length?results.map(x=>`<a href="#aula/${x.s.id}/${x.i}" data-search-result><b>${esc(x.t[0])}</b><small>${x.s.name}</small></a>`).join(''):'<p class="muted small">Nenhum conteúdo encontrado. Tente um termo mais amplo.</p>'):'<p class="muted small">Exemplos: crase, cadeia de custódia, LGPD, hierarquia…</p>';$$('[data-search-result]').forEach(a=>a.onclick=()=>$('#modal').close());};input.oninput();setTimeout(()=>input.focus(),50);}
$('#global-search').onclick=showSearch;
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();showSearch();}});
function exportBackup(){download(`rumo-a-farda-backup-${localDate()}.json`,JSON.stringify({app:'rumo-pmsc',exportedAt:new Date().toISOString(),data:state},null,2));toast('Backup exportado. Guarde-o em um lugar seguro.');}
function validState(data){if(!data||data.version!==1||typeof data.name!=='string'||data.name.length>60)return false;for(const k of ['completed','attempts','sessions'])if(!Array.isArray(data[k]))return false;for(const k of ['notes','cards','essays','essayChecks','daily','plan'])if(!data[k]||typeof data[k]!=='object'||Array.isArray(data[k]))return false;if(data.completed.some(id=>typeof id!=='string'||!SUBJECTS.some(s=>s.topics.some((_,i)=>lessonId(s,i)===id))))return false;if(Object.values(data.notes).some(x=>typeof x!=='string')||Object.values(data.essays).some(x=>typeof x!=='string'))return false;if(data.attempts.some(a=>!QUESTIONS.some(q=>q.id===a.id&&q.subject===a.subject)||typeof a.correct!=='boolean'||typeof a.date!=='string'))return false;if(data.sessions.some(s=>typeof s.minutes!=='number'||s.minutes<0||typeof s.date!=='string'))return false;if(![3,4,5,6,7].includes(data.plan.days)||data.plan.hours<.5||data.plan.hours>12||!/^\d{4}-\d{2}-\d{2}$/.test(data.plan.start))return false;if(data.exam){const e=data.exam;if(!Array.isArray(e.ids)||e.ids.length!==60||new Set(e.ids).size!==60||e.ids.some(id=>!QUESTIONS.some(q=>q.id===id))||!e.answers||!e.orders||!Number.isFinite(e.deadline)||!Number.isInteger(e.index)||e.index<0||e.index>59)return false;for(const id of e.ids){if(!Array.isArray(e.orders[id])||[...e.orders[id]].sort().join()!=='0,1,2,3,4')return false;if(id in e.answers&&![0,1,2,3,4].includes(e.answers[id]))return false;}}return true;}
function showSettings(){showModal('Seu espaço, do seu jeito.',`<p class="small muted">Seu progresso fica apenas neste navegador. Não há conta ou sincronização entre dispositivos. Exporte um backup antes de limpar dados do navegador.</p><label class="form-label" for="student-name">Como podemos chamar você?</label><input class="input" style="width:100%" id="student-name" maxlength="60" value="${esc(state.name)}"><div class="setting-actions"><button class="btn" id="save-profile">Salvar nome</button><button class="btn outline" id="backup-profile">${icon('download')} Exportar backup</button><button class="btn outline" id="import-profile">Importar backup</button></div><input type="file" accept=".json,application/json" id="import-file" hidden><div class="notice">Importar substitui o progresso atual pelos dados do arquivo. Não inclua informações sensíveis nas suas anotações.</div><button class="btn outline" id="reset-data" style="color:#a25c4c">Apagar meus dados deste navegador</button>`);$('#save-profile').onclick=()=>{state.name=$('#student-name').value.trim()||'Estudante';save();$('#modal').close();routeTo();toast('Nome atualizado. Bons estudos!');};$('#backup-profile').onclick=exportBackup;$('#import-profile').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>10000000){toast('Arquivo muito grande. Limite: 10 MB.');return;}try{const backup=JSON.parse(await file.text());if(backup.app!=='rumo-pmsc'||!validState(backup.data))throw Error();const data=backup.data;showModal('Substituir o progresso atual?',`<p>Backup válido de <b>${esc(data.name)}</b>, com ${data.completed.length} revisões concluídas e ${data.attempts.length} tentativas. Seus dados atuais serão substituídos.</p><div class="setting-actions"><button class="btn outline" id="backup-before-import">Exportar dados atuais</button><button class="btn" id="confirm-import">Importar e substituir</button></div>`);$('#backup-before-import').onclick=exportBackup;$('#confirm-import').onclick=()=>{state={...structuredClone(DEFAULT),...data};save();$('#modal').close();routeTo();toast('Backup importado com sucesso.');};}catch{toast('Backup inválido. Escolha um arquivo exportado pelo site.');}};$('#reset-data').onclick=()=>{showModal('Apagar seus dados?',`<p>Isso remove progresso, anotações, redações, tentativas e agendamentos deste navegador. Exporte um backup antes de continuar.</p><div class="setting-actions"><button class="btn outline" id="backup-before-reset">Exportar backup</button><button class="btn danger" id="confirm-reset">Apagar todos os meus dados</button></div>`);$('#backup-before-reset').onclick=exportBackup;$('#confirm-reset').onclick=()=>{state=structuredClone(DEFAULT);save();$('#modal').close();routeTo();toast('Dados apagados deste navegador.');};};}
$('#profile-btn').onclick=showSettings;
function closeMenu(){document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}
$('#menu-toggle').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));};$('#scrim').onclick=closeMenu;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('#modal').close();}});
routeTo();
